import pandas as pdimport matplotlib.pyplot as pltimport numpy as npfrom matplotlib.gridspec import GridSpecimport sysimport os# import matplotlib.pyplot as pltfrom matplotlib import rcrc('font',**{'family':'serif','serif':['Palatino']})plt.rcParams['pdf.fonttype'] = 42fig = plt.figure()# gs=GridSpec(nrows=3, ncols=4)gs=GridSpec(nrows=5, ncols=2)# for DRL_Srun = 0fileName = "DRL_S_testConvergenceCurves_run_" + str(run) + "_.pdf"all_dataset_name = ['HL']algos = ['DRL_S_run_0']gens = 180# for DRL_R# run = 0# fileName = "DRL_R_testConvergenceCurves_run_" + str(run) + "_.pdf"# all_dataset_name = ['HL']# algos = ['DRL_R_run_0']# gens = 160for i in range(0, len(all_dataset_name)):    if i<2:        ax = fig.add_subplot(gs[0:2, i])    else:        ax = fig.add_subplot(gs[2:4, i-2])    dataset_name = all_dataset_name[i]    title = 'On dataset ' + all_dataset_name[i]    plt.gca().set_title(title, fontweight='bold', size=9)    labels = algos    for algo in range(0, len(algos)):        if algos[algo] == "DRL_S_run_0":            address = '../experiment_result/scenario_' + dataset_name + '/run_' + str(        run) + '_intermediate_DRL_S_test_results_' + dataset_name + '.xlsx'        else:            address = '../experiment_result/scenario_' + dataset_name + '/run_' + str(        run) + '_intermediate_DRL_R_test_results_' + dataset_name + '.xlsx'        if not os.path.exists(address):            print("run " + str(i) + "not exist!")        else:            results = pd.read_excel(address, engine='openpyxl')[15:]            ax.plot(range(15,gens), list(results[algos[algo]]), linestyle = '-', linewidth= 0.5, marker ='.', markersize = 5)plt.figlegend(labels, loc = 'lower center', ncol = 3, bbox_to_anchor = (0.53, 0.02), labelspacing=0., fontsize = 'small')fig.text(0.5, 0.12, 'Generation', ha='center', size = 11, fontweight='bold')fig.text(0, 0.54, 'Total tardiness', va='center', rotation='vertical', size = 11, fontweight='bold')plt.tight_layout()plt.savefig("../paintingAnalysis/" + fileName)# plt.savefig("test.png")plt.show()